import{_ as i,o as e,c as l,a3 as s}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"基于时钟信号的单烘炉重息壤方案","description":"","frontmatter":{"translationSource":{"title":"基于时钟信号的单烘炉重息壤方案","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=zfM2Zf9DLRvNytZWjXcqpG","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/single-forge-heavy-xiranite-using-clock-signals"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/single-forge-heavy-xiranite-using-clock-signals"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/single-forge-heavy-xiranite-using-clock-signals"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/single-forge-heavy-xiranite-using-clock-signals"}]]},"headers":[],"relativePath":"zh/single-forge-heavy-xiranite-using-clock-signals.md","filePath":"zh/page-zfM2Zf9DLRvNytZWjXcqpG.md"}'),o={name:"zh/single-forge-heavy-xiranite-using-clock-signals.md"};function r(n,a,t,p,c,d){return e(),l("div",null,[...a[0]||(a[0]=[s('<div class="logistics-content"><span class="logistics-source-anchor" id="基于时钟信号的单烘炉重息壤方案" aria-hidden="true"></span><h1 id="基于时钟信号的单烘炉重息壤方案" tabindex="-1">基于时钟信号的单烘炉重息壤方案 <a class="header-anchor" href="#基于时钟信号的单烘炉重息壤方案" aria-label="Permalink to &quot;基于时钟信号的单烘炉重息壤方案&quot;">​</a></h1><blockquote><p>源页面 ID：<code>zfM2Zf9DLRvNytZWjXcqpG</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=zfM2Zf9DLRvNytZWjXcqpG" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>当五年后人们带着塔罗斯高容电池回到重返武陵，或许会挖出这一份失传的科技……</p><p>——kokobird</p><p><span id="source-block-pBzY7dd7zsMx3SZ4zmryDu"></span></p><span class="logistics-source-anchor" id="演示视频" aria-hidden="true"></span><h3 id="演示视频" tabindex="-1">演示视频 <a class="header-anchor" href="#演示视频" aria-label="Permalink to &quot;演示视频&quot;">​</a></h3><p><a href="https://www.bilibili.com/video/BV1yfdQBFEu7" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1yfdQBFEu7</a></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7ee3b54fedb531c4.q90-8eb436dcc134b270.webp" alt="基于时钟信号的单烘炉重息壤方案"></p><p><span id="source-block-V1P5EQSkeyQ0eOWEfGABK8"></span></p><span class="logistics-source-anchor" id="基本原理解说" aria-hidden="true"></span><h3 id="基本原理解说" tabindex="-1">基本原理解说 <a class="header-anchor" href="#基本原理解说" aria-label="Permalink to &quot;基本原理解说&quot;">​</a></h3><ol><li><p>使用两组拆灌机+一组采种机，利用传送带控制相同周期，同时启动产生稳定同步的时钟信号。每生产14块息壤，10块息壤转而生产1块息壤，4块息壤变为5壤晶废液</p></li><li><p>传送带设置为17格长度，连同两个机子产生38秒周期（视频中为18格40秒周期，比较稳，后来发现调成17格也可以）</p></li><li><p>稳定碳块信号用锦草种子控制，做息壤用的水由拆灌机控制，做重息壤用的壤晶废液由拆灌机控制</p></li><li><p>调整传输传送带和水管的长度来控制信号延迟，来使得生产对轴</p></li></ol><p><span id="source-block-suuwxMTCaWf8PcR0zNEuJd"></span></p><span class="logistics-source-anchor" id="难点" aria-hidden="true"></span><h3 id="难点" tabindex="-1">难点 <a class="header-anchor" href="#难点" aria-label="Permalink to &quot;难点&quot;">​</a></h3><ol><li><p>烘炉门口的分流器轮询顺序不好控制。生产重息壤前必须10块息壤在门口2x5列队，并在两步内塞进。如果分流器中的息壤下一步不向前出而是侧路出，就会多2秒等待间隔导致崩溃（为什么最开始说40秒有点容错）</p></li><li><p>5壤晶废液必须很快地进入烘炉，但是拆灌机只能按2秒1个生产。所以用管道做了个整流器，通过不同的管道长度让间隔2秒出来的5废液接近同时到达烘炉。然而，这个整流器做起来很麻烦，我调整管道长度多了管道桥以后分流顺序都变了。</p></li><li><p>生产出的14息壤，如果用七分器其实也有同样整流问题，这里直接让4块息壤优先进反应池，剩下的溢流来解决。</p></li><li><p>对轴问题。2路息壤输入10块息壤，但是必须要在最短时间内全部进入烘炉。所以水必须要后进，才能让碳块把息壤卡在外面让它们排好队。同时排队时间不能太长，否则就会让后面生产出的碳块卡住，下一轮能容纳息壤进来的空间就不到10个。</p></li><li><p>基本上允许烘炉待机的时间越长难点会越少。能待机10秒的话以上四点可能直接消失。</p></li></ol><p><span id="source-block-lvXmi04Y6wZK6AqRrXzNAg"></span></p><span class="logistics-source-anchor" id="踩过的坑" aria-hidden="true"></span><h3 id="踩过的坑" tabindex="-1">踩过的坑 <a class="header-anchor" href="#踩过的坑" aria-label="Permalink to &quot;踩过的坑&quot;">​</a></h3><ol><li><p>试图用固体准入口来复制信号形成同步时钟——下线就烂了</p></li><li><p>试图用一个拆解机拆两种瓶子达成10水5壤晶废液的顺序，用准入口做分拣——下线就烂了</p></li><li><p>试图用磁带法把七分五的息壤整流——下线就烂了</p></li><li><p>试图用管道磁带法来整流壤晶废液——混管时钟我算不清</p></li></ol><p><span id="source-block-vxE22YOQkvP9lAUpY243Iy"></span></p><span class="logistics-source-anchor" id="未解之谜" aria-hidden="true"></span><h3 id="未解之谜" tabindex="-1">未解之谜 <a class="header-anchor" href="#未解之谜" aria-label="Permalink to &quot;未解之谜&quot;">​</a></h3><ol><li><p>虽然传送带周期是38秒，但是实测下来稳定运行时周期是非常严格的38.5秒。。。。。。找不到0.5是哪来的</p></li><li><p>1.3版本更新后烂了，1.4版本更新后竟然没烂</p></li></ol></div>',1)])])}const f=i(o,[["render",r]]);export{u as __pageData,f as default};
